from typing import Dict, List, Tuple

WEEKDAYS = ["Monday", "Tuesday"]
WORK_START = 9 * 60
WORK_END = 17 * 60
DURATION = 30

def to_minutes(hhmm: str) -> int:
    h, m = map(int, hhmm.split(":"))
    return h * 60 + m

def to_hhmm(mins: int) -> str:
    return f"{mins // 60:02d}:{mins % 60:02d}"

def overlaps(start: int, end: int, other_start: int, other_end: int) -> bool:
    return start < other_end and end > other_start

def is_free(day: str, start: int, end: int, schedules: Dict[str, Dict[str, List[Tuple[int, int]]]]) -> bool:
    for busy_start, busy_end in schedules.get(day, []):
        if overlaps(start, end, busy_start, busy_end):
            return False
    return True

schedules = {
    "Jeffrey": {
        "Monday": [],
        "Tuesday": [],
    },
    "Harold": {
        "Monday": [
            (to_minutes("9:00"), to_minutes("10:00")),
            (to_minutes("10:30"), to_minutes("17:00")),
        ],
        "Tuesday": [
            (to_minutes("9:00"), to_minutes("9:30")),
            (to_minutes("10:30"), to_minutes("11:30")),
            (to_minutes("12:30"), to_minutes("13:30")),
            (to_minutes("14:30"), to_minutes("15:30")),
            (to_minutes("16:00"), to_minutes("17:00")),
        ],
    },
}

# Harold's scheduling preference: avoid Monday, and avoid Tuesday before 14:30.
avoid_intervals = {
    "Monday": [(0, 24 * 60)],
    "Tuesday": [(to_minutes("9:00"), to_minutes("14:30"))],
}

def is_preferred(day: str, start: int, end: int) -> bool:
    for bad_start, bad_end in avoid_intervals.get(day, []):
        if overlaps(start, end, bad_start, bad_end):
            return False
    return True

candidates = []
for day in WEEKDAYS:
    for start in range(WORK_START, WORK_END - DURATION + 1, 30):
        end = start + DURATION
        if not is_free(day, start, end, schedules):
            continue
        if not is_preferred(day, start, end):
            continue
        candidates.append((day, start, end))

day, start, end = candidates[0]
print([day, to_hhmm(start), to_hhmm(end)])
